#!/bin/bash
set -e

# ==============================================================
# kaviancrypto v7.5 Pro Terminal - Complete Zero-Km Installer
# Can be run on a brand-new server OR safely upgrade an existing one!
# Optional CLI Migration:
#   bash install_kaviancrypto_v7_5.sh /path/to/backup.json|.zip
#
# Updates in v7.5:
#   - Full-State Backup & Disaster Recovery Model (Schema v2):
#       * Captures 100% of Settings (Markets, Telegram, Proxy,
#         Schedules, Direction Mode, Theme, Auth)
#       * Captures ALL Open Positions (with TP/SL & TG reply IDs)
#         + 31-Day Closed History + Sent Signal Dedupe Cache
#       * Captures Active Strategy Script + ALL Saved Presets +
#         ALL Strategy Version History
#       * Captures Latest Signals Table + TV Watchlist + Scan Summary
#       * SHA-256 Integrity Checksum + Pre-Restore Inspector
#       * Dual Download Format: Full Bundle (.zip) & Snapshot (.json)
#       * Selective Restore Checkboxes + Auto Pre-Restore Safety Snapshot
#       * Local Server Snapshots Manager (Last 10 rotated on disk)
#       * Zero-Logout Session Continuity on Restore
# + Weekly/Monthly P&L Reports + 31-Day Auto-Archive Retention
# + Split Check TP/SL Now & Visual TP/SL Report + Working Manual Exit
# + Strategy Studio Pro (Per-Strategy Parameters Menu + Presets +
#   Multi-TF Matrix + 500-Bar Walk-Forward Backtester)
# + Unified Obsidian Gold Pro Palette (Obsidian & Bento HUD)
# ==============================================================

APP_DIR="/opt/kaviancrypto"
PORT="8888"
RESTORE_ARG="${1:-}"

echo "========================================================"
echo "  kaviancrypto v7.5 Pro - Complete Zero-Km Installer"
echo "  Full-State Backup & Disaster Recovery (.zip / .json)"
echo "========================================================"

echo "=== [1/6] Stopping existing service (if running) & preparing $APP_DIR ==="
systemctl stop kaviancrypto.service 2>/dev/null || true
mkdir -p "$APP_DIR" "$APP_DIR/backups"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancrypto_v7_5.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancrypto_v7_5.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancrypto_v7_5.sh" 2>/dev/null || true
fi

echo "=== [2/6] Installing system prerequisites ==="
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl

echo "=== [3/6] Extracting verified kaviancrypto v7.5 core files ==="
